-- Local pilot schema. Application connections use farmos_app, never the bootstrap owner.
CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_users(id text PRIMARY KEY,username text NOT NULL UNIQUE,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),disabled boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS organizations(id text PRIMARY KEY,name text NOT NULL,revision bigint NOT NULL DEFAULT 0,meta jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS memberships(organization_id text REFERENCES organizations(id),user_id text REFERENCES app_users(id),role text NOT NULL CHECK(role IN('owner','manager','employee','accountant','readonly')),worker_id text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash text PRIMARY KEY,user_id text REFERENCES app_users(id),csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS records(organization_id text NOT NULL REFERENCES organizations(id),kind text NOT NULL,id text NOT NULL,payload jsonb NOT NULL,position integer NOT NULL DEFAULT 0,version bigint NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,kind,id));
CREATE TABLE IF NOT EXISTS record_links(organization_id text NOT NULL,from_kind text NOT NULL,from_id text NOT NULL,relation text NOT NULL,to_kind text NOT NULL,to_id text NOT NULL,PRIMARY KEY(organization_id,from_kind,from_id,relation,to_kind,to_id),FOREIGN KEY(organization_id,from_kind,from_id)REFERENCES records(organization_id,kind,id)ON DELETE CASCADE,FOREIGN KEY(organization_id,to_kind,to_id)REFERENCES records(organization_id,kind,id)DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS command_receipts(organization_id text NOT NULL REFERENCES organizations(id),id text NOT NULL,user_id text NOT NULL REFERENCES app_users(id),request_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id));
CREATE TABLE IF NOT EXISTS audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations(id),user_id text NOT NULL REFERENCES app_users(id),action text NOT NULL,command_id text NOT NULL,revision bigint NOT NULL,at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ledger_journals(organization_id text NOT NULL,id text NOT NULL,posted_at timestamptz NOT NULL,description text NOT NULL,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id)REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS ledger_postings(organization_id text NOT NULL,journal_id text NOT NULL,line integer NOT NULL,account text NOT NULL CHECK(account IN('cash','inventory','cropWip','cattleWip','expense','revenue','equity')),cents bigint NOT NULL,enterprise_id text NOT NULL DEFAULT '',field_id text NOT NULL DEFAULT '',group_id text NOT NULL DEFAULT '',asset_id text NOT NULL DEFAULT '',animal_id text NOT NULL DEFAULT '',PRIMARY KEY(organization_id,journal_id,line),FOREIGN KEY(organization_id,journal_id)REFERENCES ledger_journals(organization_id,id)ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS records_query ON records(organization_id,kind);
CREATE INDEX IF NOT EXISTS auth_expiry ON auth_sessions(expires_at);
CREATE INDEX IF NOT EXISTS audit_tenant ON audit_events(organization_id,at);
CREATE OR REPLACE FUNCTION tenant_allowed(tenant text)RETURNS boolean LANGUAGE sql STABLE AS $$SELECT tenant=current_setting('app.organization_id',true)$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['records','record_links','command_receipts','audit_events','ledger_journals','ledger_postings'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename=t AND policyname='tenant_isolation')THEN EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_allowed(organization_id)) WITH CHECK(tenant_allowed(organization_id))',t);END IF;END LOOP;END$$;
-- Defense in depth: financial queries require a trusted API-established financial role.
DROP POLICY IF EXISTS tenant_isolation ON ledger_journals;
CREATE POLICY tenant_isolation ON ledger_journals USING(tenant_allowed(organization_id)AND current_setting('app.role',true)IN('owner','accountant')) WITH CHECK(tenant_allowed(organization_id)AND current_setting('app.role',true)='owner');
DROP POLICY IF EXISTS tenant_isolation ON ledger_postings;
CREATE POLICY tenant_isolation ON ledger_postings USING(tenant_allowed(organization_id)AND current_setting('app.role',true)IN('owner','accountant')) WITH CHECK(tenant_allowed(organization_id)AND current_setting('app.role',true)='owner');
INSERT INTO schema_migrations(version)VALUES(1)ON CONFLICT DO NOTHING;
